            for (int i = 0; i < teamNumber; ++i) {
                if (nArray[i] != 1 || nodeList.get(i).getHasGet().booleanValue()) continue;
                arrayList.add(nodeList.get(i));
            }
            if (arrayList.isEmpty()) {
                stack.pop();
                continue;
            }
            stack.push((Node)arrayList.get((int)(Math.random() * (double)arrayList.size())));
            stack.getTop().setTrue();
        }
    }

    static class Node {
        private int index;
        private boolean hasGet;

        public Node(int n) {
            this.index = n;
            this.hasGet = false;
        }

        public int getIndex() {
            return this.index;
        }

        public Boolean getHasGet() {
            return this.hasGet;
        }

        public void setTrue() {
            this.hasGet = true;
        }

        public void setFalse() {
            this.hasGet = false;
        }
    }

    static class Stack {
        private List<Node> nodeList = new ArrayList<Node>();

        Stack() {
        }

        public void push(Node node) {
            this.nodeList.add(node);
        }

        public Node pop() {
            Node node = this.getTop();
            this.nodeList.remove(this.nodeList.size() - 1);
            return node;
        }

        public Node getTop() {
            return this.nodeList.get(this.nodeList.size() - 1);
        }

        public String toString() {
            StringBuilder stringBuilder = new StringBuilder("[ " + this.nodeList.get(0).getIndex());
            for (int i = 1; i < this.nodeList.size(); ++i) {
                stringBuilder.append(" --> " + this.nodeList.get(i).getIndex());
            }
            stringBuilder.append(" ]");
            return stringBuilder.toString();
        }

        public Boolean isFull() {
            if (this.nodeList.size() == teamNumber) {
                return true;
            }
            return false;
        }

        public Boolean isEmpty() {
            if (this.nodeList.size() == 0) {
                return true;
            }
            return false;
        }
    }
}

