//快速排序方法
private static void quickSort(String[] samples, int start, int end) {
    if(start >= end) {
        return;
    }
    String pivot = samples[start];
    int low = start;
    int high = end;
    while(low < high) {
        while(low < high && myCompare(samples[high], pivot) >= 0) {
            high --;
        }
        samples[low] = samples[high];
        while(low < high && myCompare(samples[low], pivot) <= 0) {
            low ++;
        }
        samples[high] = samples[low];
    }
    samples[low] = pivot;
    quickSort(samples, start, low - 1);
    quickSort(samples, low + 1, end);
}
//按照给定顺序比较两个字符串的方法
private static int myCompare(String a, String b) {
    int length = Math.min(a.length(), b.length());
    for(int i = 0; i < length; i ++) {
        char charA = a.charAt(i);
        char charB = b.charAt(i);
        if(charA != charB) {
            return charA - charB;
        }
    }
    return a.length() - b.length();
}

