    //初始化所有的List
    private static void initialList() {
        System.out.print("请输入学院总数：");
        schoolNumber = scanner.nextInt();
        System.out.print("请输入男子项目总数：");
        manProjectNumber = scanner.nextInt();
        System.out.print("请输入女子项目总数：");
