        for(int i = 1; i <= schoolNumber; i ++) {
            schoolList.add(new School(i));
        }
        for(int i = 1; i <= projectNumber; i ++) {
            boolean isMaleProject = i <= manProjectNumber;
            System.out.print("项目" + i + "（" + (isMaleProject ? "男子" : "女子") + "）取前三名请输入3，取前五名请输入5：");
            boolean isThreeProject = scanner.nextInt() == 3;
            projectList.add(new Project(i, isMaleProject, isThreeProject));
        }
    }
    //输出菜单栏并根据选择调用相应的方法
    private static void menu() {
        System.out.println("\n=============== 运动会分数统计系统 ===============");
        System.out.println("1. 录入成绩");
        System.out.println("2. 输出学院总分");
