        int choice = scanner.nextInt();
        switch(choice) {
            case 1:
                inputScore();
                break;
            case 2:
                schoolScoreInfo();
                break;
            case 3:
                outputScore();
                break;
            case 4:
                searchInNumber();
                break;
            case 5:
                writeToFile();
                break;
            case 0:
                scanner.close();
                System.exit(0);
            default:
                System.out.println("输入选择有误！");
        }
    }
    //按照项目读入前三名或前五名
    private static void inputScore() {
        System.out.print("请输入项目编号（1 - " + projectNumber + "）：");
        int projectLabel = scanner.nextInt();
        if(projectLabel < 1 || projectLabel > projectNumber) {
            System.out.println("该项目不存在！");
            return;
        }
        Project project = projectList.get(projectLabel - 1);
        project.clearWinnerSchools();
        int winnerNumber = project.getIsThreeProject() ? 3 : 5;
        for(int i = 0; i < winnerNumber; i ++) {
            System.out.print("请输入第" + (i + 1) + "名的学院编号：");
            int schoolLabel = scanner.nextInt();
            if(schoolLabel < 1 || schoolLabel > schoolNumber) {
                System.out.println("该学院不存在，请重新输入！");
                i --;
                continue;
            }
            School school = schoolList.get(schoolLabel - 1);
            int score = getScore(project, i);
            school.addTotalScore(score);
            if(project.getIsMaleProject()) {
                school.addMaleScore(score);
            } else {
                school.addFemaleScore(score);
            }
            project.addWinnerSchools(school);
        }
        System.out.println("项目" + projectLabel + "的成绩录入完毕！");
