        Map<Integer, Integer> scoreOfProject = new HashMap<>();
        for(Project project : projectList) {
            ArrayList<School> winnerSchools = project.getWinnerSchools();
            for(int i = 0; i < winnerSchools.size(); i ++) {
                if(winnerSchools.get(i) == target) {
                    int score = getScore(project, i);
                    scoreOfProject.put(project.getProjectLabel(), score);
                    System.out.println("项目" + project.getProjectLabel()
                            + "（" + (project.getIsMaleProject() ? "男子" : "女子") + "）"
                            + "第" + (i + 1) + "名，得分" + score);
                }
            }
        }
        if(scoreOfProject.isEmpty()) {
            System.out.println("该学院暂未取得任何名次！");
        }
        System.out.println("该学院总分为：" + target.getTotalScore());
    }
    //按照项目编号查询
    private static void searchByProject() {
        System.out.print("请输入项目编号（1 - " + projectNumber + "）：");
        int projectLabel = scanner.nextInt();
        if(projectLabel < 1 || projectLabel > projectNumber) {
            System.out.println("该项目不存在！");
            return;
        }
        Project project = projectList.get(projectLabel - 1);
        ArrayList<School> winnerSchools = project.getWinnerSchools();
        if(winnerSchools.isEmpty()) {
            System.out.println("该项目暂未录入成绩！");
            return;
        }
        System.out.println("项目" + projectLabel + "（" + (project.getIsMaleProject() ? "男子" : "女子") + "）的名次如下：");
        for(int i = 0; i < winnerSchools.size(); i ++) {
            System.out.println("第" + (i + 1) + "名：学院" + winnerSchools.get(i).getSchoolLabel()
                    + "，得分" + getScore(project, i));
        }
    }
    //根据名次获取相应的分数
    private static int getScore(Project project, int rank) {
        int[] scores = project.getIsThreeProject() ? new int[]{5, 3, 2} : new int[]{7, 5, 3, 2, 1};
        if(rank < 0 || rank >= scores.length) {
            return 0;
        }
        return scores[rank];
    }
    //序列化将对象存入文件
    private static void writeToFile() {
        try {
            ObjectOutputStream outputStream = new ObjectOutputStream(new FileOutputStream("score.dat"));
            outputStream.writeInt(schoolNumber);
            outputStream.writeInt(manProjectNumber);
            outputStream.writeInt(womanProjectNumber);
            outputStream.writeObject(schoolList);
            outputStream.writeObject(projectList);
            outputStream.close();
            System.out.println("数据已经存入文件score.dat！");
        } catch (Exception e) {
            System.out.println("写入文件失败：" + e.getMessage());
        }
    }
    //反序列化将对象从文件读出
    @SuppressWarnings("unchecked")
    private static void readFromFile() {
        File file = new File("score.dat");
        if(!file.exists()) {
            System.out.println("文件不存在，转为手动初始化！");
            initialList();
            return;
        }
        try {
            ObjectInput inputStream = new ObjectInputStream(new FileInputStream(file));
            schoolNumber = inputStream.readInt();
            manProjectNumber = inputStream.readInt();
            womanProjectNumber = inputStream.readInt();
            projectNumber = manProjectNumber + womanProjectNumber;
            schoolList = (ArrayList<School>) inputStream.readObject();
            projectList = (ArrayList<Project>) inputStream.readObject();
            inputStream.close();
            System.out.println("数据已经从文件score.dat读出！");
        } catch (Exception e) {
            System.out.println("读取文件失败，转为手动初始化：" + e.getMessage());
            initialList();
        }
    }
}

